import{_ as a,b as o,c as e,I as r}from"./chunks/framework.C6cPs9Ia.js";const l="/LQY/images/moment-2.jpg",s="/LQY/images/moment-3.jpg",u=JSON.parse('{"title":"谷子收纳大作战：吧唧的秩序与混沌","description":"高中生的谷子收纳整理记录：吧唧保护、痛包与预算管理","frontmatter":{"title":"谷子收纳大作战：吧唧的秩序与混沌","date":"2026-08-17T00:00:00.000Z","tags":["谷子","日常"],"cover":"/LQY/images/moment-1.jpg","head":[["meta",{"name":"description","content":"高中生的谷子收纳整理记录：吧唧保护、痛包与预算管理"}],["meta",{"name":"keywords","content":"谷子, 吧唧, 痛包, 收纳"}]]},"headers":[],"relativePath":"posts/badge-collection.md","filePath":"posts/badge-collection.md"}'),d={name:"posts/badge-collection.md"};function i(n,t,c,g,p,h){return o(),e("div",null,[...t[0]||(t[0]=[r('<p>攒了两年谷子，书桌抽屉终于膨胀到关不上的程度。趁着暑假尾巴，进行了一次大整理，顺便把经验教训记录成文。</p><hr><h2 id="现场惨况-整理前" tabindex="-1">现场惨况（整理前） <a class="header-anchor" href="#现场惨况-整理前" aria-label="Permalink to &quot;现场惨况（整理前）&quot;">​</a></h2><p>先自首：整理前的抽屉状态是——三层吧唧叠着压、色纸卷成筒、亚克力挂件互相刮擦。最惨的一个吧唧表面已经有了三道细划痕，凶手是同抽屉的另一枚吧唧背面。</p><div class="danger custom-block"><p class="custom-block-title">血的教训</p><p>吧唧的印刷面很脆弱，<strong>背面金属边也会刮花别人的印刷面</strong>。任何&quot;先堆着回头再整理&quot;的想法，最终都会变成划痕。</p></div><h2 id="本次采购的收纳装备" tabindex="-1">本次采购的收纳装备 <a class="header-anchor" href="#本次采购的收纳装备" aria-label="Permalink to &quot;本次采购的收纳装备&quot;">​</a></h2><table tabindex="0"><thead><tr><th>装备</th><th>用途</th><th>价格区间</th></tr></thead><tbody><tr><td>吧唧保护套（透明）</td><td>单枚隔离，防刮花</td><td>约 0.3 元/个</td></tr><tr><td>吧唧收纳册</td><td>分格平放，竖立收纳</td><td>15-30 元</td></tr><tr><td>色纸保护套 + 硬胶片</td><td>防弯折</td><td>约 0.5 元/套</td></tr><tr><td>亚克力收纳盒</td><td>挂件分类</td><td>10 元上下</td></tr><tr><td>干燥剂</td><td>南方防潮必备</td><td>白菜价</td></tr></tbody></table><h2 id="分类哲学" tabindex="-1">分类哲学 <a class="header-anchor" href="#分类哲学" aria-label="Permalink to &quot;分类哲学&quot;">​</a></h2><p>整理的核心争议是<strong>按什么分</strong>。本人的结论：按&quot;爱&quot;的浓度分，不按作品分。</p><ol><li><strong>圣物区</strong>：最珍视的那几枚，收纳册第一页，不外借不佩戴不挂闲鱼</li><li><strong>日常佩戴区</strong>：痛包常驻阵容，每季度轮换一次</li><li><strong>普通收藏区</strong>：其余按作品分格，册子里躺着</li><li><strong>待嫁区</strong>：重复购入的谷子，攒着和同学交换</li></ol><h2 id="痛包配置" tabindex="-1">痛包配置 <a class="header-anchor" href="#痛包配置" aria-label="Permalink to &quot;痛包配置&quot;">​</a></h2><p><img src="'+l+'" alt="" data-fancybox="gallery"></p><p>痛包遵循&quot;<strong>一主二辅</strong>&quot;原则：</p><ul><li>主位：当季推的角色，C 位</li><li>辅位×2：常青树角色，氛围组</li><li>挂件链：不超过三条，再多走路会响，会社死</li></ul><p><img src="'+s+'" alt="" data-fancybox="gallery"></p><h2 id="预算管理-学生版" tabindex="-1">预算管理（学生版） <a class="header-anchor" href="#预算管理-学生版" aria-label="Permalink to &quot;预算管理（学生版）&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">高中生谷子经济学</p><ul><li><strong>月上限</strong>：零花钱的 30%，雷打不动</li><li><strong>优先级</strong>：推的新谷 &gt; 补货复购 &gt; 顺手 aesthetics</li><li><strong>二手市场</strong>：有原价 6 折捡漏的快乐，也有被抬价的愤怒，谨记&quot;急了就输&quot;</li><li><strong>最重要的规则</strong>：谷子是爱的表达，不是投资。想着升值的瞬间，快乐就没了</li></ul></div><p>整理完的书桌抽屉，现在关得上、拉得顺，每一枚吧唧都躺在自己的格子里。妈妈再也不会问&quot;你这些铁片片到底有什么好收集的了&quot;——大概。</p><p>开学快乐，各位。</p>',19)])])}const b=a(d,[["render",i]]);export{u as __pageData,b as default};
